using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Mvc;using TransPort.Api.Controllers;using TransPort.Api.Modules.Transporte.DTOs;using TransPort.Api.Modules.Transporte.Repositories;
namespace TransPort.Api.Tests;
public sealed class TransportesControllerTests
{[Fact]public async Task Listar_PropagaAlcance(){var r=new F();await C(r,6,"Empleado").Listar(null,null,null,default);Assert.Equal(new AlcanceTransporte(6,false),r.A);}[Fact]public async Task Crear_RetornaId(){var r=new F{Id=8};var x=Assert.IsType<OkObjectResult>(await C(r,1,"AdministradorGeneral").Crear(new(){SedeId=1,VehiculoId=1,ConductorId=1,Tipo="Nacional",Origen="A",Destino="B",DescripcionCarga="Carga",PesoCarga=1,FechaSalidaPlanificada=DateTime.Now},default));Assert.Equal(8,Assert.IsType<ResultadoTransporteDto>(x.Value).Id);}[Fact]public async Task Obtener_Inexistente_NotFound()=>Assert.IsType<NotFoundResult>(await C(new F(),1,"AdministradorGeneral").Obtener(9,default));[Fact]public async Task Incidencia_PropagaAlcance(){var r=new F();Assert.IsType<OkObjectResult>(await C(r,4,"Operativo").Incidencia(1,new(){Tipo="Retraso",Severidad="Baja",Descripcion="Prueba"},default));Assert.Equal(new AlcanceTransporte(4,false),r.A);}[Fact]public void ExcluyeCliente(){var a=typeof(TransportesController).GetCustomAttributes(typeof(AuthorizeAttribute),true).Cast<AuthorizeAttribute>().Single();Assert.DoesNotContain("Cliente",a.Roles??"");}
private static TransportesController C(ITransporteRepository r,int id,params string[]roles){var cs=new List<Claim>{new(ClaimTypes.NameIdentifier,id.ToString())};cs.AddRange(roles.Select(x=>new Claim(ClaimTypes.Role,x)));return new(r){ControllerContext=new(){HttpContext=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity(cs,"T"))}}};}private sealed class F:ITransporteRepository{public long Id{get;init;}public AlcanceTransporte?A{get;private set;}public Task<IReadOnlyList<TransporteViajeListadoDto>>ListarAsync(string?e,string?t,int?s,AlcanceTransporte a,CancellationToken ct){A=a;return Task.FromResult<IReadOnlyList<TransporteViajeListadoDto>>([]);}public Task<TransporteViajeDetalleDto?>ObtenerAsync(long id,AlcanceTransporte a,CancellationToken ct)=>Task.FromResult<TransporteViajeDetalleDto?>(null);public Task<TransporteOpcionesDto>OpcionesAsync(AlcanceTransporte a,CancellationToken ct)=>Task.FromResult(new TransporteOpcionesDto([],[],[],[]));public Task<int>CrearVehiculoAsync(CrearVehiculoTransporteRequest x,AlcanceTransporte a,CancellationToken ct)=>Task.FromResult(1);public Task<int>CrearConductorAsync(CrearConductorTransporteRequest x,AlcanceTransporte a,CancellationToken ct)=>Task.FromResult(1);public Task<long>CrearViajeAsync(CrearViajeTransporteRequest x,AlcanceTransporte a,CancellationToken ct){A=a;return Task.FromResult(Id);}public Task<bool>EstadoViajeAsync(long id,EstadoViajeTransporteRequest x,AlcanceTransporte a,CancellationToken ct)=>Task.FromResult(true);public Task<long>CrearIncidenciaAsync(long id,CrearIncidenciaTransporteRequest x,AlcanceTransporte a,CancellationToken ct){A=a;return Task.FromResult(Id);}public Task<bool>ResolverIncidenciaAsync(long id,string r,AlcanceTransporte a,CancellationToken ct)=>Task.FromResult(true);public Task<bool>EliminarViajeAsync(long id,int u,CancellationToken ct)=>Task.FromResult(true);public Task<bool>EliminarRecursoAsync(string t,int id,int u,CancellationToken ct)=>Task.FromResult(true);}}
